<?php
$branches = rows('SELECT * FROM branches ORDER BY branch_name');
$teachers = rows('SELECT * FROM teachers ORDER BY full_name');
$branchFilter = query_int('branch'); $teacherFilter = query_int('teacher');
$where = []; $params = [];
if ($branchFilter) { $where[] = 's.branch_id = ?'; $params[] = $branchFilter; }
if ($teacherFilter) { $where[] = 's.teacher_id = ?'; $params[] = $teacherFilter; }
$sql = 'SELECT s.*, t.full_name, b.branch_name FROM schedules s JOIN teachers t ON t.id=s.teacher_id JOIN branches b ON b.id=s.branch_id' . ($where ? ' WHERE '.implode(' AND ', $where) : '');
$list = rows($sql . ' ORDER BY s.day_of_week,s.period_start', $params);
$totalPeriods = array_sum(array_map(static fn(array $row): int => (int)$row['period_end'] - (int)$row['period_start'] + 1, $list));
$dayCount = array_fill_keys(range(1,7),0); $branchCount = [];
foreach ($branches as $branch) $branchCount[$branch['branch_name']] = 0;
foreach ($list as $item) { $dayCount[(int)$item['day_of_week']] += (int)$item['period_end']-(int)$item['period_start']+1; $branchCount[$item['branch_name']]++; }
$maxDay = max(1, max($dayCount)); $maxBranch = max(1, ...array_values($branchCount ?: [1]));
$activeTeachers = count(array_unique(array_column($list,'teacher_id')));
$activeBranches = count(array_unique(array_column($list,'branch_id')));
?>
<div class="page-heading heading-with-action"><div><div class="eyebrow">BẢNG ĐIỀU KHIỂN</div><h1>Tổng quan hệ thống <span class="heading-dot">.</span></h1><p>Theo dõi và điều phối hoạt động giảng dạy trên mọi cơ sở.</p></div><a class="btn btn-primary" href="<?= e(app_url('schedule-form')) ?>"><svg><use href="#i-plus"/></svg> Phân công lịch dạy</a></div>
<form method="get" class="filter-bar"><input type="hidden" name="page" value="dashboard"><span class="filter-caption"><svg><use href="#i-filter"/></svg> Bộ lọc dữ liệu</span><select name="branch" aria-label="Lọc cơ sở"><option value="">Tất cả cơ sở</option><?php foreach ($branches as $b): ?><option value="<?= (int)$b['id'] ?>"<?= chosen($branchFilter,$b['id']) ?>><?= e($b['branch_name']) ?></option><?php endforeach; ?></select><select name="teacher" aria-label="Lọc giảng viên"><option value="">Tất cả giảng viên</option><?php foreach ($teachers as $t): ?><option value="<?= (int)$t['id'] ?>"<?= chosen($teacherFilter,$t['id']) ?>><?= e($t['full_name']) ?></option><?php endforeach; ?></select><button class="btn btn-dark btn-sm" type="submit">Áp dụng</button><a href="<?= e(app_url('dashboard')) ?>" class="text-link">Đặt lại</a></form>
<div class="metrics-grid">
  <div class="metric-card"><div class="metric-icon blue"><svg><use href="#i-calendar"/></svg></div><span class="metric-name">Lịch giảng dạy</span><strong class="metric-value"><?= count($list) ?></strong><span class="metric-note">Buổi học hàng tuần</span></div>
  <div class="metric-card"><div class="metric-icon mint"><svg><use href="#i-clock"/></svg></div><span class="metric-name">Tổng số tiết</span><strong class="metric-value"><?= $totalPeriods ?></strong><span class="metric-note">Tiết được phân công</span></div>
  <div class="metric-card"><div class="metric-icon amber"><svg><use href="#i-users"/></svg></div><span class="metric-name">Giảng viên tham gia</span><strong class="metric-value"><?= $activeTeachers ?></strong><span class="metric-note">/ <?= count($teachers) ?> giảng viên toàn hệ thống</span></div>
  <div class="metric-card"><div class="metric-icon violet"><svg><use href="#i-building"/></svg></div><span class="metric-name">Cơ sở có lịch</span><strong class="metric-value"><?= $activeBranches ?></strong><span class="metric-note">/ <?= count($branches) ?> cơ sở đang quản lý</span></div>
</div>
<div class="dashboard-charts"><section class="panel"><div class="panel-heading"><div><h2>Phân bổ tiết học</h2><p>Số tiết được phân công theo ngày trong tuần</p></div><span class="pill">Theo tuần</span></div><div class="bar-chart" role="img" aria-label="Biểu đồ tổng số tiết theo thứ trong tuần"><?php foreach ($dayCount as $day => $count): ?><div class="bar-column"><span class="bar-value"><?= $count ?></span><div class="bar-rail"><div class="bar-fill<?= $day === 1 ? ' bar-accent' : '' ?>" style="height:<?= max(3,round($count/$maxDay*100)) ?>%"></div></div><span class="bar-label"><?= e(short_day($day)) ?></span></div><?php endforeach; ?></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Phân bổ theo cơ sở</h2><p>Số buổi dạy tại mỗi địa điểm</p></div><span class="panel-icon">◫</span></div><div class="branch-chart"><?php if (!$branches): ?><div class="empty-inline">Chưa có cơ sở đào tạo.</div><?php endif; ?><?php foreach ($branchCount as $name=>$count): ?><div class="branch-bar-item"><div class="branch-bar-label"><span><?= e($name) ?></span><strong><?= $count ?> buổi</strong></div><div class="branch-bar-track"><div class="branch-bar-fill" style="width:<?= round($count/$maxBranch*100) ?>%"></div></div></div><?php endforeach; ?></div><div class="chart-note"><span class="online-dot"></span> Biểu đồ cập nhật theo bộ lọc phía trên</div></section></div>
<section class="panel"><div class="panel-heading"><div><h2>Lịch giảng dạy trong tuần</h2><p>Danh sách các buổi dạy theo thứ và tiết học</p></div><a class="text-link with-arrow" href="<?= e(app_url('schedules')) ?>">Xem tất cả <svg><use href="#i-arrow"/></svg></a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>HỌC PHẦN</th><th>GIẢNG VIÊN</th><th>CƠ SỞ</th><th>THỜI GIAN</th><th>PHÒNG</th></tr></thead><tbody><?php foreach (array_slice($list,0,7) as $item): ?><tr><td><strong><?= e($item['subject_name']) ?></strong></td><td><span class="avatar-inline"><?= e(initials($item['full_name'])) ?></span><?= e($item['full_name']) ?></td><td><?= e($item['branch_name']) ?></td><td><span class="tag-blue"><?= e(short_day((int)$item['day_of_week'])) ?></span> <?= e(period_label((int)$item['period_start'],(int)$item['period_end'])) ?></td><td><?= e($item['room']) ?></td></tr><?php endforeach; ?><?php if (!$list): ?><tr><td colspan="5" class="table-empty">Chưa có lịch phù hợp. Hãy thêm một lịch dạy mới.</td></tr><?php endif; ?></tbody></table></div></section>
